impl Rule {
    /// The rule as a frame stores it: the language's tag in the high bits, the
    /// position in [`Rule::ALL`] in the low 9 bits.
    #[expect(
        clippy::as_conversions,
        reason = "a fieldless `repr(u16)` enum has no `From` impl for its discriminant"
    )]
    pub(crate) const fn code(self) -> u16 {
        crate::tag::CPP | self as u16
    }

    /// The rule a frame's code names; [`Rule::Root`] for a code that is
    /// not the language's, such as the empty state's.
    pub(crate) fn from_code(code: u16) -> Rule {
        if code & 0xfe00 != crate::tag::CPP {
            return Rule::Root;
        }
        Rule::ALL
            .get(usize::from(code & 0x1ff))
            .copied()
            .unwrap_or(Rule::Root)
    }
}

impl rules::Tabled for Cpp {
    fn pat_start(pat: Pat) -> rules::Start {
        pat.start()
    }

    fn tables(rule: Rule) -> &'static rules::Tables<Self> {
        static TABLES: [std::sync::OnceLock<rules::Tables<Cpp>>; Rule::ALL.len()] =
            [const { std::sync::OnceLock::new() }; Rule::ALL.len()];
        #[expect(
            clippy::as_conversions,
            reason = "a fieldless `repr(u16)` enum has no `From` impl"
        )]
        let index = rule as usize;
        TABLES[index].get_or_init(move || rules::Tables::build(rule.data()))
    }
}

const _: () = assert!(
    87 <= <super::engine::Cpp as crate::rules::Grammar>::GROUPS,
    "a pattern's table names a capture group past the grammar's GROUPS"
);
